<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { ArrowRight, ImagePlus, Check, ScanSearch, BookOpen, ArrowUpRight } from 'lucide-vue-next'
import AssetPreview from '../components/AssetPreview.vue'
import { useAssets, metric } from '../services/studio'
import { useAuthStore } from '../stores/auth'
import { useImageDraft } from '../stores/imageDraft'
import api from '../services/api'
const auth=useAuthStore(), router=useRouter(), draft=useImageDraft(), {assets,loading,error,load}=useAssets()
const selection=ref(0),source=ref(''),sourceKind=ref(''),sourceBlob=ref<Blob|null>(null),sourceError=ref(''),sourceLoading=ref(false)
const examples=computed(()=>assets.value.filter(a=>a.preview_available && a.format==='glb')), selected=computed(()=>examples.value.find(a=>a.id===selection.value))
let version=0
async function loadCases() {if(!auth.token)return;await load();selection.value=examples.value[0]?.id||0}
async function loadSource() { const request=++version;sourceError.value='';sourceBlob.value=null;if(source.value)URL.revokeObjectURL(source.value);source.value='';if(!selection.value)return;sourceLoading.value=true;try{const response=await api.get(`/studio/assets/${selection.value}/reference`,{responseType:'blob',params:{allow_current_project:true}});if(request!==version)return;sourceBlob.value=response.data;source.value=URL.createObjectURL(response.data);sourceKind.value=response.headers['x-reference-kind']||'current_project'}catch{if(request===version)sourceError.value='此历史记录没有可读取的参考图，可以查看真实模型或打开所属项目。'}finally{if(request===version)sourceLoading.value=false} }
function useReference(destination='/generate'){if(!sourceBlob.value)return;draft.image=new File([sourceBlob.value],`reference-${selection.value}.png`,{type:sourceBlob.value.type||'image/png'});void router.push(destination)}
onMounted(loadCases);watch(selection,loadSource);watch(()=>auth.token,value=>{if(value)void loadCases();else{assets.value=[];selection.value=0;version++;if(source.value)URL.revokeObjectURL(source.value);source.value='';sourceBlob.value=null}})
onUnmounted(()=>{version++;if(source.value)URL.revokeObjectURL(source.value)})
const faqs=[{q:'生成前为什么要先预处理图片？',a:'上传并配置后，先进入参考图预处理。先检查原图轮廓、构图与细节，默认保留人物及原背景，按比例居中和留白。复杂背景可另外预览去背景效果；轻度锐化为可选项。对照原图确认头发、四肢和配饰完整后，再确认输入并开始生成。抠图误删主体时可保留原图继续。'},{q:'生成必须使用额外的视觉语言模型吗？',a:'当前本机 Pixal3D 直接读取确认后的图片，不需要先生成文字角色描述。独立视觉语言模型适合辅助检查参考图或建议参数，不是本次图生 3D 的必选前置服务。'},{q:'为什么正面像参考图，背面却不一样？',a:'单张图片只提供可见部分，背面由模型推断。建议在预览器中旋转检查；缺失的背面细节不能依靠提高纹理分辨率直接恢复。'},{q:'为什么不直接选择 2048px？',a:'当前本机标准配置为 1024px。2048px 仍是实验选项，纹理阶段可能超过 6GB 显存；更高分辨率不保证五官或纹理位置更准确。'},{q:'生成失败后，在哪里继续？',a:'到生成任务中打开失败任务，查看具体错误。先确认本机生成服务在线；如果是显存不足，改用 1024px 和中等面数。再使用任务详情中的重新生成。'},{q:'结构检查通过，就能直接用于游戏或动画吗？',a:'不能据此确定。结构检查不评价外观相似度，也不提供骨骼绑定、动画或游戏拓扑。请结合用途检查面数、材质、背面和导入效果。'},{q:'为什么带纹理的模型没有独立贴图下载？',a:'GLB 可以把贴图嵌入模型文件。预览页未显示独立贴图时，先下载 GLB 并在 Blender 等软件中查看材质；不要将独立贴图数量为零理解为没有纹理。'},{q:'修复后能撤销吗？',a:'修复保存为独立版本，原始模型保留。可以在检查与修复页选择历史修复版本，分别查看和下载。自动结构修复不会重新生成人脸或补画纹理。'}]
</script>
<template><main class="page tool-page guide-page"><header class="library-heading"><div><p class="eyebrow">从第一张图开始</p><h1>使用指南与案例</h1><p>知道如何准备、怎样检查，让每一次生成都有可追溯的结果。</p></div><RouterLink class="library-button primary-action" to="/generate">开始生成<ArrowRight :size="15" /></RouterLink></header><nav class="guide-index" aria-label="指南目录"><a href="#reference">准备参考图</a><a href="#parameters">选择参数</a><a href="#inspection">检查与修复</a><a href="#cases">真实案例</a><a href="#questions">常见问题</a></nav><section id="reference" class="tool-card guide-section"><div class="guide-section-title"><span class="guide-line-mark"><ImagePlus :size="23" /></span><div><p class="eyebrow">输入决定起点</p><h2>准备一张清楚的参考图</h2></div></div><div class="guide-two-column"><div><h3>更适合开始的图片</h3><ul class="guide-list"><li>单一主体、轮廓完整，手脚与配饰尽量不出画。</li><li>背景简单、光线均匀，减少遮挡与大面积阴影。</li><li>尽量使用清晰原图；上传支持 PNG、JPG、WEBP，最大 20MB。</li></ul><RouterLink class="library-button" to="/prepare">整理参考图<ArrowRight :size="15" /></RouterLink></div><div class="guide-note"><h3>遇到这些情况，先调整</h3><p>多人合照、细小主体、长裙遮住身体、透明饰品或复杂披风，都会增加重建难度。先裁剪出单个主体，再预览抠图是否误删了发丝或配饰。</p><p>处理后的图片可以先下载检查，也能带入生成页；应用图片不会自动提交生成任务。</p></div></div></section><section id="parameters" class="tool-card guide-section"><div class="guide-section-title"><span class="guide-line-mark"><BookOpen :size="23" /></span><div><p class="eyebrow">先从已验证的配置开始</p><h2>选择生成参数</h2></div></div><div class="guide-parameter-row"><div><strong>高质量</strong><span>本机 Pixal3D 工作流</span></div><div><strong>1024px</strong><span>推荐纹理配置</span></div><div><strong>中面数</strong><span>目标上限约 50 万面</span></div><div><strong>GLB + PBR</strong><span>模型与材质一起交付</span></div></div><p class="tool-hint">实际面数以结果为准。当前可用模式由生成服务返回，未接入的档位不能提交；2048px 为实验值。页面配置说明不代表每张图都能获得同样效果。</p><RouterLink class="text-link" to="/presets">查看和保存生成预设 →</RouterLink></section><section id="inspection" class="tool-card guide-section"><div class="guide-section-title"><span class="guide-line-mark"><ScanSearch :size="23" /></span><div><p class="eyebrow">让结果可检查</p><h2>完成后，先旋转一圈</h2></div></div><div class="guide-two-column"><div><h3>外观需要你来判断</h3><p>依次查看正脸、侧面、背面、头顶和衣物接缝；切换材质、轮廓与线框，区分纹理问题和几何问题。在检查页保存人工复核备注。</p></div><div><h3>结构修复提供什么</h3><p>列出各网格的退化面、重复面、边界和 UV 状态；可清理无效面、修正绕序，并对无 UV 网格填补部分小孔。修复另存版本，支持前后对照和下载。</p></div></div><p class="tool-hint">开放衣物或头发的边界不一定是错误。自动修复不处理大孔重建、五官相似度、纹理重新绘制、骨骼或动画。</p><RouterLink class="library-button" to="/repair">选择模型检查<ArrowRight :size="15" /></RouterLink></section><section id="cases" class="tool-card guide-section"><div class="tool-section-head"><div><p class="eyebrow">实际文件 · 实际结果</p><h2>你的真实生成案例</h2></div><span class="tool-badge">仅本人可见</span></div><p class="tool-hint">这里读取账号已完成的模型，便于回看参数与效果；不会将你的图片和作品公开给其他账号。</p><div v-if="!auth.token" class="guide-note"><p>登录后查看自己已经生成的真实案例。</p><RouterLink class="library-button" to="/auth?redirect=/guide%23cases">登录查看<ArrowRight :size="15" /></RouterLink></div><p v-else-if="loading" class="tool-hint" role="status">正在读取你的生成结果…</p><div v-else-if="error" class="library-error" role="alert">{{error}} <button class="library-button quiet" @click="loadCases">重试</button></div><template v-else-if="selected"><select v-model="selection" class="library-select guide-case-select" aria-label="选择真实生成案例"><option v-for="item in examples" :key="item.id" :value="item.id">{{item.name}} · #{{item.id}}</option></select><div class="guide-case-pair"><figure><div class="guide-reference"><img v-if="source" :src="source" :alt="sourceKind==='snapshot'?'本次任务输入快照':'项目当前参考图'" /><span v-else class="tool-hint">{{sourceLoading?'正在读取参考图…':sourceError}}</span></div><figcaption>{{sourceKind==='snapshot' && source?'本次任务输入快照':'项目当前参考图'}}<small v-if="sourceKind!=='snapshot' && source">历史任务没有输入快照，此图可能与当时输入不同。</small></figcaption></figure><figure><div class="guide-case-model"><AssetPreview :task-id="selected.id" :format="selected.format" :available="selected.preview_available" /></div><figcaption>任务 #{{selected.id}} 的真实 GLB<small>可拖拽旋转；以模型实际外观为准。</small></figcaption></figure></div><div class="guide-case-facts"><span>{{selected.parameters.texture_resolution || '未记录'}}px 请求纹理</span><span>{{metric(selected.metadata.face_count)}} 面</span><span>{{selected.metadata.file_size_mb?.toFixed(2) || '未记录'}} MB</span></div><div class="library-actions"><RouterLink class="library-button" :to="`/workflow/${selected.id}?step=preview`">打开完整模型<ArrowUpRight :size="15" /></RouterLink><RouterLink class="library-button quiet" :to="`/repair/${selected.id}`">检查此模型</RouterLink><button class="library-button quiet" :disabled="!sourceBlob || sourceLoading" @click="useReference('/generate')">使用此参考图重新配置</button><button class="library-button quiet" :disabled="!sourceBlob || sourceLoading" @click="useReference('/prepare')">整理此参考图</button></div></template><div v-else class="guide-note"><p>完成第一个模型后，这里会显示真实结果。</p><RouterLink class="text-link" to="/generate">上传图片开始 →</RouterLink></div></section><section id="questions" class="guide-section"><div class="guide-section-title"><h2>常见问题</h2></div><div class="guide-faq"><details v-for="item in faqs" :key="item.q"><summary>{{item.q}}</summary><p>{{item.a}}</p></details></div></section></main></template>
